import React, { useState } from 'react';

const MiniSlider = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const images = [
    "https://via.placeholder.com/600x300?text=Slide+1",
    "https://via.placeholder.com/600x300?text=Slide+2",
    "https://via.placeholder.com/600x300?text=Slide+3" 
  ];

  const changeSlide = (direction) => {
    const totalSlides = images.length;
    setCurrentSlide((prevSlide) => (prevSlide + direction + totalSlides) % totalSlides);
  };

  return (
    <div style={{  // Set background color and reduce width
      position: 'relative',
      width: '300px', // Change width to desired size
      maxWidth: '300px', // Adjust if needed
      margin: 'auto',
      backgroundColor: '#F5F9FF',
      overflow: 'hidden',
    }}>
      <div style={{
        display: 'flex',
        transition: 'transform 0.5s ease',
        transform: `translateX(-${currentSlide * 100}%)`,
      }}>
        {images.map((src, index) => (
          <div key={index} style={{
            minWidth: '100%',
            boxSizing: 'border-box',
          }}>
            <img src={src} alt={`Slide ${index + 1}`} style={{
              width: '100%',
              height: 'auto',
            }} />
          </div>
        ))}
      </div>
      <button // Left navigation button
        onClick={() => changeSlide(-1)}
        style={{
          position: 'absolute',
          top: '50%',
          left: '0',
          transform: 'translateY(-50%)',
          backgroundColor: 'rgba(0, 0, 0, 0.5)',
          color: 'white',
          border: 'none',
          padding: '10px',
          cursor: 'pointer',
        }}
      >
        &#10094;
      </button>
      <button // Right navigation button
        onClick={() => changeSlide(1)}
        style={{
          position: 'absolute',
          top: '50%',
          right: '0',
          transform: 'translateY(-50%)',
          backgroundColor: 'rgba(0, 0, 0, 0.5)',
          color: 'white',
          border: 'none',
          padding: '10px',
          cursor: 'pointer',
        }}
      >
        &#10095;
      </button>
    </div>
  );
};

export default MiniSlider;
